#[derive(Default)]struct Owner{work:u64,bytes:u64,refuse:bool}impl wire::Admission for Owner{fn reserve(&mut self,w:u64,b:u64)->Result<(),()>{if self.refuse{return Err(())}self.work+=w;self.bytes+=b;Ok(())}fn check(&mut self)->Result<(),()>{Ok(())}}
fn raw()->Vec<u8>{let base=std::path::Path::new("/home/ec2-user/ml-dataset-resume-20261029/owned-search-durable-checkpoint-20261107/fixtures/1238229-positive/live/payloads");let mut b=std::fs::read(base.join("boolean-owned-pattern-0-snapshot-0-chunk-0.bin.part")).unwrap();b.extend(std::fs::read(base.join("boolean-owned-pattern-0-snapshot-0-chunk-1.bin.part")).unwrap());b}
fn check(raw:Vec<u8>)->prefix::Audit{prefix::admit(raw,wire::Limits::default(),Instant::now()+Duration::from_secs(60),&mut Owner::default())}
#[test]fn actual_complete_and_every_byte_cut_are_distinguished(){let b=raw();assert_eq!(b.len(),6761);let mut first=None;for end in 0..=b.len(){let a=check(b[..end].to_vec());assert!(a.result().is_ok(),"{end}: {:?}",a.result());if a.binding_prefix().is_some(){first.get_or_insert(end);}assert_eq!(a.result()==Ok(prefix::State::CompleteWire),end==b.len());assert_eq!(a.consumed(),end);}println!("first_complete_identity={:?}",first);assert!(first.unwrap()<4096);}
#[test]fn actual_refused_committed_chunk_is_valid_prefix_not_complete(){let p="/home/ec2-user/ml-dataset-resume-20261029/owned-search-durable-checkpoint-20261107/fixtures/1238229-refusal/live/payloads/boolean-owned-pattern-0-snapshot-0-chunk-0.bin.part";let a=check(std::fs::read(p).unwrap());assert_eq!(a.result(),Ok(prefix::State::IncompleteIdentityAvailable));assert!(a.binding_prefix().unwrap().get("identity").is_some());}
#[test]fn observed_magic_tag_key_and_schema_mutations_reject_before_eof(){let b=raw();for(i,v,end)in [(0,b'X',1),(10,5,11),(19,2,20),(28,b'X',29)]{let mut x=b[..end].to_vec();x[i]=v;assert!(check(x).result().is_err(),"offset{i}")}}
#[test]fn fixed_partial_count_mismatch_is_not_truncation(){let mut b=raw()[..12].to_vec();b[11]=19;assert_eq!(check(b).result(),Err(wire::Failure::Shape));}
#[test]fn complete_invalid_suffix_invalidates_retained_identity(){let mut b=raw();*b.last_mut().unwrap()=0;let a=check(b);assert_eq!(a.result(),Err(wire::Failure::Shape));assert!(a.binding_prefix().is_none());}
#[test]fn resources_and_deadline_never_fall_back_to_prefix(){let b=raw();let mut o=Owner{refuse:true,..Default::default()};let a=prefix::admit(b[..4096].to_vec(),wire::Limits::default(),Instant::now()+Duration::from_secs(10),&mut o);assert_eq!(a.result(),Err(wire::Failure::OwnerReserve));assert!(a.binding_prefix().is_none());let a=prefix::admit(vec![],wire::Limits::default(),Instant::now(),&mut Owner::default());assert_eq!(a.result(),Err(wire::Failure::Deadline));for l in [wire::Limits{work:10,..Default::default()},wire::Limits{allocation_bytes:10,..Default::default()},wire::Limits{nodes:2,..Default::default()}]{let a=prefix::admit(b[..4096].to_vec(),l,Instant::now()+Duration::from_secs(10),&mut Owner::default());assert!(a.result().is_err());assert!(a.binding_prefix().is_none());}}
#[test]fn accepted_owner_charges_match_and_raw_is_retained(){let b=raw();let mut o=Owner::default();let a=prefix::admit(b[..4096].to_vec(),wire::Limits::default(),Instant::now()+Duration::from_secs(10),&mut o);assert_eq!(a.raw(),&b[..4096]);assert_eq!((a.charge().work,a.charge().bytes),(o.work,o.bytes));}
fn field_value_offset(b:&[u8],key:&str)->usize{b.windows(key.len()).position(|v|v==key.as_bytes()).unwrap()+key.len()}
#[test]fn truncated_utf8_must_have_a_possible_valid_completion(){let b=raw();let i=field_value_offset(&b,"diagnostic");assert_eq!(b[i],3);for(len,tail,valid)in [(4,vec![0xf0],true),(4,vec![0xf0,0x90],true),(4,vec![0xf0,0x80],false),(2,vec![0xf0],false),(3,vec![0xe0,0xa0],true),(3,vec![0xe0,0x80],false),(2,vec![0xc0],false),(2,vec![0xc2,0x41],false)]{let mut x=b[..i+1].to_vec();x.extend_from_slice(&(len as u64).to_le_bytes());x.extend(tail);let a=check(x);assert_eq!(a.result().is_ok(),valid,"len{len}:{:?}",a.result());if !valid{assert!(a.binding_prefix().is_none());}}}
#[test]fn partial_lengths_refuse_observed_caps_and_fixed_hash_length(){let b=raw();let i=field_value_offset(&b,"diagnostic");let mut x=b[..i+1].to_vec();x.extend_from_slice(&[0xff,0xff]);assert_eq!(check(x).result(),Err(wire::Failure::StringCap));let i=field_value_offset(&b,"public_sha256");assert_eq!(b[i],4);let mut x=b[..i+1].to_vec();x.push(31);assert_eq!(check(x).result(),Err(wire::Failure::Shape));let mut l=wire::Limits::default();l.nodes=2;let x=raw()[..12].to_vec();assert_eq!(prefix::admit(x,l,Instant::now()+Duration::from_secs(10),&mut Owner::default()).result(),Err(wire::Failure::Nodes));}
#[test]fn malformed_suffix_after_complete_identity_is_rejected_at_first_tag(){let b=raw();let i=field_value_offset(&b,"diagnostic");for tag in [0,1,2,4,5,6,7,255]{let mut x=b[..i+1].to_vec();x[i]=tag;let a=check(x);if tag==0{assert!(a.result().is_ok());}else{assert!(a.result().is_err(),"tag{tag}");assert!(a.binding_prefix().is_none());}}}
#[test]fn invalid_ack_hash_prefix_rejects_even_before_full_hash(){let b=raw();let i=field_value_offset(&b,"last_event_sha256");assert_eq!(b[i],3);let mut x=b[..i+10].to_vec();x[i+9]=b'G';assert_eq!(check(x).result(),Err(wire::Failure::Shape));}
#[test]fn generic_diagnostic_duplicate_key_cannot_hide_behind_truncation(){let b=raw();let i=field_value_offset(&b,"lift_records");let mut x=b[..i].to_vec();x.push(6);x.extend_from_slice(&2u64.to_le_bytes());for child in [Some(0u8),None]{x.push(3);x.extend_from_slice(&1u64.to_le_bytes());x.push(b'a');if let Some(tag)=child{x.push(tag)}}let a=check(x);assert_eq!(a.result(),Err(wire::Failure::DuplicateKey));assert!(a.binding_prefix().is_none());}
#[test]fn complete_wire_trailing_bytes_reject_and_identity_is_unavailable(){let mut b=raw();b.push(0);let a=check(b);assert_eq!(a.result(),Err(wire::Failure::Trailing));assert!(a.binding_prefix().is_none());}
